func newMixedConfig(opts ...MixedOption) *mixedConfig {
	c := &mixedConfig{
		Fixture: DefaultMixedFixture(),
		clock:   clock.RealClock(),
		without: map[string]struct{}{},
	}
	for _, o := range opts {
		o(c)
	}
	return c
}

